/// Fixed server Connection ID byte length generated by each QUIC shard.
pub(crate) const QUIC_SHARD_CID_LEN: usize = 8;

/// Maximum queued incoming datagrams per QUIC shard before tail-dropping like a UDP socket buffer.
pub(crate) const QUIC_SHARD_QUEUE_CAP: usize = 4096;

/// Maximum recycled datagram byte buffers retained per QUIC shard pool.
pub(crate) const QUIC_SHARD_POOL_CAP: usize = 1024;

/// Default allocation capacity for pooled incoming QUIC datagram buffers.
pub(crate) const QUIC_DATAGRAM_INIT_CAP: usize = 2048;

/// Requested OS UDP receive/send socket buffer size for the exclusive multi-shard QUIC socket.
pub(crate) const QUIC_SHARD_SOCKET_BUF_SIZE: usize = 2 * 1024 * 1024;

/// Thread name for the dedicated non-starved exclusive-UDP receive dispatcher.
pub(crate) const QUIC_DISPATCHER_THREAD_NAME: &str = "hyperlane-quic-rx";
